package net.consensys.linea.zktracer.module.ecdata;

import net.consensys.linea.UnitTestWatcher;
import net.consensys.linea.reporting.TracerTestBase;
import net.consensys.linea.testing.BytecodeRunner;
import org.apache.tuweni.bytes.Bytes;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;

/**
 * Tests for the EcData module which handles elliptic curve operations in precompiled contracts.
 *
 * <p>This test suite ensures proper functioning of the zkEVM tracer for EC operations
 * including ECADD, ECMUL, ECRECOVER, and ECPAIRING. These operations are critical for
 * cryptographic verification in smart contracts.
 *
 * <p>The tests execute compiled bytecode that calls the elliptic curve precompiles with
 * different input parameters to verify correct trace generation and constraint validation.
 */
@ExtendWith(UnitTestWatcher.class)
public class EcDataTest extends TracerTestBase {

  @Test
  void testEcData() {
    // resources/contracts/ec_data/EcDataBigTest.sol
    BytecodeRunner.of(
            Bytes.fromHexString(
                ""))
        .run(testInfo);
  }

  @Test
  void testEcRecoverWithEmptyExt() {
    BytecodeRunner.of(
            Bytes.fromHexString(
                ""))
        .run(testInfo);
  }
}
